import {StyleSheet, Text, View} from 'react-native';
import React from 'react';
import {createStackNavigator} from '@react-navigation/stack';
import DiseaseInfoScreen from '../screens/main/DiseaseInfoScreen';
import ListOfDiseases from '../screens/main/ListOfDiseases';
import FvrtScreen from '../screens/main/FvrtScreen';

const Stack = createStackNavigator();

const SavedNavigation = () => {
  return (
    <Stack.Navigator>
        <Stack.Screen
        name="FvrtScreen"
        component={FvrtScreen}
        options={{headerShown: false}}
      />
      <Stack.Screen
        name="diseaseInfoScreen"
        component={DiseaseInfoScreen}
        options={{headerShown: false}}
      />
      <Stack.Screen
        name="listOfDiseases"
        component={ListOfDiseases}
        options={{headerShown: false}}
      />
    </Stack.Navigator>
  );
};

export default SavedNavigation;

const styles = StyleSheet.create({});